**Design note (10 lines):**
Tokens are produced by a character scanning loop (O(n), no recursion). Parsing uses an adapted shunting-yard algorithm with an explicit operator stack and an output stack of AST nodes — O(n), zero Python recursion. The AST is compiled to a flat bytecode list (list of `(opcode, arg)` tuples) via an explicit-stack post-order traversal, with `if` lowered to `COND_JUMP`/`JUMP` for laziness. Evaluation is a single `while` loop over a program counter and a value stack. `Expr` is immutable after construction; `evaluate()` allocates a fresh stack per call, so concurrent calls are safe.

### solution.py
```python
"""Safe formula engine for spreadsheet cells.

Design: tokens via scanning loop; shunting-yard parser (explicit stacks, O(n),
no recursion); AST compiled to flat bytecode via iterative post-order traversal;
evaluation is a PC-loop with a value stack.  Expr is immutable → thread-safe.
"""

from __future__ import annotations

import math
from collections.abc import Mapping

# ─── Exceptions ────────────────────────────────────────────────────────────────

class ExprError(Exception):
    pass

class ExprSyntaxError(ExprError):
    def __init__(self, message: str, position: int):
        super().__init__(message)
        self.message = message
        self.position = position

class ExprNameError(ExprError):
    def __init__(self, message: str, name: str = ""):
        super().__init__(message)
        self.name = name

class ExprEvalError(ExprError):
    pass

# ─── Tokenizer ─────────────────────────────────────────────────────────────────

# Token representation: (type_str, value_str, start_pos)
_TN = 'N'   # number
_TI = 'I'   # identifier
_TO = 'O'   # operator / punctuation
_TV = 'V'   # invalid character
_TE = 'E'   # end-of-input

def _tokenize(src: str) -> list[tuple[str, str, int]]:
    tokens: list[tuple[str, str, int]] = []
    i = 0
    n = len(src)
    while i < n:
        ch = src[i]
        # whitespace
        if ch in ' \t\n\r':
            i += 1
            continue
        # number starting with digit
        if '0' <= ch <= '9':
            start = i
            while i < n and '0' <= src[i] <= '9':
                i += 1
            if i < n and src[i] == '.':
                i += 1
                while i < n and '0' <= src[i] <= '9':
                    i += 1
            # exponent
            if i < n and src[i] in 'eE':
                i += 1
                if i < n and src[i] in '+-':
                    i += 1
                if i >= n or not ('0' <= src[i] <= '9'):
                    # malformed number
                    tokens.append((_TV, src[start:i], start))
                    continue
                while i < n and '0' <= src[i] <= '9':
                    i += 1
            tokens.append((_TN, src[start:i], start))
        # number starting with dot
        elif ch == '.':
            start = i
            if i + 1 < n and '0' <= src[i + 1] <= '9':
                i += 1
                while i < n and '0' <= src[i] <= '9':
                    i += 1
                if i < n and src[i] in 'eE':
                    i += 1
                    if i < n and src[i] in '+-':
                        i += 1
                    if i >= n or not ('0' <= src[i] <= '9'):
                        tokens.append((_TV, src[start:i], start))
                        continue
                    while i < n and '0' <= src[i] <= '9':
                        i += 1
                tokens.append((_TN, src[start:i], start))
            else:
                tokens.append((_TV, '.', start))
                i += 1
        # identifier
        elif ('a' <= ch <= 'z') or ('A' <= ch <= 'Z') or ch == '_':
            start = i
            while i < n:
                c = src[i]
                if ('a' <= c <= 'z') or ('A' <= c <= 'Z') or ('0' <= c <= '9') or c == '_':
                    i += 1
                else:
                    break
            tokens.append((_TI, src[start:i], start))
        # operators / punctuation
        elif ch in '+-*/%()^,':
            tokens.append((_TO, ch, i))
            i += 1
        elif ch == '<':
            if i + 1 < n and src[i + 1] == '=':
                tokens.append((_TO, '<=', i))
                i += 2
            else:
                tokens.append((_TO, '<', i))
                i += 1
        elif ch == '>':
            if i + 1 < n and src[i + 1] == '=':
                tokens.append((_TO, '>=', i))
                i += 2
            else:
                tokens.append((_TO, '>', i))
                i += 1
        elif ch == '=':
            if i + 1 < n and src[i + 1] == '=':
                tokens.append((_TO, '==', i))
                i += 2
            else:
                tokens.append((_TV, '=', i))
                i += 1
        elif ch == '!':
            if i + 1 < n and src[i + 1] == '=':
                tokens.append((_TO, '!=', i))
                i += 2
            else:
                tokens.append((_TV, '!', i))
                i += 1
        else:
            # any other character (non-ascii, $, [, ', etc.)
            tokens.append((_TV, ch, i))
            i += 1
    tokens.append((_TE, '', n))
    return tokens

# ─── AST node helpers (plain tuples for speed) ─────────────────────────────────
# ('num', float)
# ('var', name)
# ('unary', op, operand)
# ('bin', op, left, right)
# ('cmp', op, left, right)
# ('func', name, [args], pos)

# ─── Function table ────────────────────────────────────────────────────────────

_FUNCS: dict[str, tuple[int, int]] = {  # name → (min_args, max_args)
    'abs': (1, 1),
    'sqrt': (1, 1),
    'min': (1, -1),   # -1 = unbounded
    'max': (1, -1),
    'round': (1, 2),
    'if': (3, 3),
}

# ─── Shunting-yard parser ───────────────────────────────────────────────────────

_PREC: dict[str, int] = {'<':1,'<=':1,'>':1,'>=':1,'==':1,'!=':1,
                         '+':2,'-':2,'*':3,'/':3,'%':3,'^':5}

def _op_prec(op_entry: tuple) -> int:
    kind = op_entry[0]
    if kind == 'cmp':
        return 1
    if kind == 'bin':
        return _PREC[op_entry[1]]
    if kind == 'un':
        return 4
    return 0  # paren / func

def _apply_op(op_entry: tuple, out: list) -> None:
    kind = op_entry[0]
    if kind == 'bin':
        b = out.pop()
        a = out.pop()
        out.append(('bin', op_entry[1], a, b))
    elif kind == 'un':
        a = out.pop()
        out.append(('unary', op_entry[1], a))
    elif kind == 'cmp':
        b = out.pop()
        a = out.pop()
        out.append(('cmp', op_entry[1], a, b))

def _pop_to(out: list, ops: list, stop_kinds: set[str]) -> tuple | None:
    """Pop operators onto *out* until a kind in *stop_kinds* is on top.
    Returns the stopping entry (not popped) or None."""
    while ops:
        if ops[-1][0] in stop_kinds:
            return ops[-1]
        _apply_op(ops.pop(), out)
    return None

def _pop_higher(out: list, ops: list, prec: int, left_assoc: bool) -> None:
    while ops:
        k = ops[-1][0]
        if k in ('paren', 'func'):
            break
        p = _op_prec(ops[-1])
        if left_assoc:
            if p >= prec:
                _apply_op(ops.pop(), out)
            else:
                break
        else:  # right-assoc
            if p > prec:
                _apply_op(ops.pop(), out)
            else:
                break

def _parse(tokens: list[tuple], src_len: int) -> tuple:
    out: list = []       # AST value stack
    ops: list = []       # operator / marker stack
    expecting_value = True
    n = len(tokens)
    i = 0

    while i < n:
        tt, tv, tp = tokens[i]

        if tt == _TE:
            break

        # ── invalid token ──
        if tt == _TV:
            raise ExprSyntaxError(f"Invalid character '{tv}'", tp)

        # ── number ──
        if tt == _TN:
            if not expecting_value:
                raise ExprSyntaxError("Unexpected number", tp)
            val = float(tv)
            if math.isinf(val) or math.isnan(val):
                raise ExprSyntaxError("Number overflow", tp)
            out.append(('num', val))
            expecting_value = False
            i += 1
            continue

        # ── identifier ──
        if tt == _TI:
            if not expecting_value:
                raise ExprSyntaxError("Unexpected identifier", tp)
            # lookahead: is next token '(' ?
            j = i + 1
            if j < n and tokens[j][0] == _TO and tokens[j][1] == '(':
                ops.append(('func', tv, tp, 1))  # argc starts at 1
                i = j + 1  # skip IDENT and '('
                expecting_value = True
                continue
            out.append(('var', tv))
            expecting_value = False
            i += 1
            continue

        # ── operators / punctuation ──
        if tt == _TO:
            op = tv

            if op == '(':
                if not expecting_value:
                    raise ExprSyntaxError("Unexpected '('", tp)
                ops.append(('paren', tp))
                expecting_value = True
                i += 1
                continue

            if op == ')':
                if expecting_value:
                    # Empty arg list for a function, or () for grouping
                    if ops and ops[-1][0] == 'func':
                        fname, fpos, _ = ops[-1][1], ops[-1][2], ops[-1][3]
                        ops.pop()
                        out.append(('func', fname, [], fpos))
                        expecting_value = False
                        i += 1
                        continue
                    raise ExprSyntaxError("Expected expression", tp)
                # pop operators until matching paren/func
                found = False
                while ops:
                    k = ops[-1][0]
                    if k == 'paren':
                        ops.pop()
                        found = True
                        break
                    if k == 'func':
                        fname, fpos, argc = ops[-1][1], ops[-1][2], ops[-1][3]
                        ops.pop()
                        args = [out.pop() for _ in range(argc)][::-1]
                        out.append(('func', fname, args, fpos))
                        found = True
                        break
                    _apply_op(ops.pop(), out)
                if not found:
                    raise ExprSyntaxError("Unmatched ')'", tp)
                expecting_value = False
                i += 1
                continue

            if op == ',':
                if expecting_value:
                    raise ExprSyntaxError("Expected expression", tp)
                found = False
                while ops:
                    k = ops[-1][0]
                    if k == 'func':
                        ops[-1] = ('func', ops[-1][1], ops[-1][2], ops[-1][3] + 1)
                        found = True
                        break
                    if k == 'paren':
                        raise ExprSyntaxError("Unexpected ','", tp)
                    _apply_op(ops.pop(), out)
                if not found:
                    raise ExprSyntaxError("Unexpected ','", tp)
                expecting_value = True
                i += 1
                continue

            # comparison operators
            if op in ('<', '<=', '>', '>=', '==', '!='):
                if expecting_value:
                    raise ExprSyntaxError("Expected expression", tp)
                _pop_higher(out, ops, 1, True)
                # non-associativity check
                if ops and ops[-1][0] == 'cmp':
                    raise ExprSyntaxError("Non-associative operator", tp)
                ops.append(('cmp', op, tp))
                expecting_value = True
                i += 1
                continue

            # + - : unary or binary
            if op in '+-':
                if expecting_value:
                    ops.append(('un', op, tp))
                    # expecting_value stays True (need operand)
                    i += 1
                    continue
                # binary
                prec = 2
                _pop_higher(out, ops, prec, True)
                ops.append(('bin', op, tp))
                expecting_value = True
                i += 1
                continue

            # * / %
            if op in ('*', '/', '%'):
                if expecting_value:
                    raise ExprSyntaxError("Expected expression", tp)
                _pop_higher(out, ops, 3, True)
                ops.append(('bin', op, tp))
                expecting_value = True
                i += 1
                continue

            # ^
            if op == '^':
                if expecting_value:
                    raise ExprSyntaxError("Expected expression", tp)
                _pop_higher(out, ops, 5, False)  # right-assoc
                ops.append(('bin', '^', tp))
                expecting_value = True
                i += 1
                continue

            raise ExprSyntaxError(f"Unexpected '{op}'", tp)

        i += 1  # safety

    # ── end of input ──
    if expecting_value:
        raise ExprSyntaxError("Unexpected end", src_len)

    while ops:
        k = ops[-1][0]
        if k == 'paren':
            raise ExprSyntaxError("Unmatched '('", src_len)
        _apply_op(ops.pop(), out)

    if len(out) != 1:
        raise ExprSyntaxError("Incomplete expression", src_len)

    return out[0]

# ─── Compile-time validation ───────────────────────────────────────────────────

def _validate(node: tuple, best: list) -> None:
    """Walk AST iteratively; collect the leftmost function-name/arity violation."""
    stack = [node]
    while stack:
        n = stack.pop()
        k = n[0]
        if k == 'func':
            fname, args, pos = n[1], n[2], n[3]
            spec = _FUNCS.get(fname)
            if spec is None:
                if best[0] is None or pos < best[1]:
                    best[0], best[1], best[2] = fname, pos, 'name'
            else:
                lo, hi = spec
                argc = len(args)
                if argc < lo or (hi >= 0 and argc > hi):
                    if best[0] is None or pos < best[1]:
                        best[0], best[1], best[2] = fname, pos, 'arity'
            for a in args:
                stack.append(a)
        elif k in ('unary',):
            stack.append(n[2])
        elif k in ('bin', 'cmp'):
            stack.append(n[2]); stack.append(n[3])
        # 'num', 'var' – nothing

